-- Demo data for AgileSim: a finished Startup Flow session with two teams and a
-- second session that is still in the lobby.
-- GENERATED by backend/scripts/generate_demo_data.py - do not edit by hand.
-- Run as the schema owner after the migrations. Running it again replaces the demo
-- sessions; it does not touch other sessions.
BEGIN;

DELETE FROM game_sessions WHERE join_code IN ('DEMO01', 'DEMO02');
DELETE FROM facilitators WHERE email = 'demo.facilitator@example.com';

CREATE TEMPORARY TABLE demo_scenario ON COMMIT DROP AS
SELECT id FROM scenarios WHERE code = 'startup-flow' AND version = 1;
CREATE TEMPORARY TABLE demo_stage ON COMMIT DROP AS
SELECT st.code, st.id
  FROM scenario_stages st JOIN demo_scenario s ON s.id = st.scenario_id;

