INSERT INTO card_movements (team_id, card_id, day, from_stage_id, from_state,
                            to_stage_id, to_state, actor_participant_id,
                            actor_facilitator_id, request_id, is_manual, comment,
                            occurred_at)
SELECT CAST(v.team AS uuid), CAST(v.card AS uuid), v.day, fs.id,
       CAST(v.from_state AS varchar), ts.id, CAST(v.to_state AS varchar),
       CAST(v.participant AS uuid), CAST(v.facilitator AS uuid),
       CAST(v.request AS uuid), v.is_manual, CAST(v.comment AS text),
       CAST(v.at AS timestamptz)
  FROM (VALUES
          ('bef5f642-dfa7-588b-ada6-db77c165203e', '54785af5-483d-5daa-9e8e-7fe45b54b11f', 7, NULL, NULL, 'development', 'in_progress', NULL, 'bb259a53-09cd-55bc-923b-7e521bc3be9e', '50925001-4ccb-5866-9242-678d000a3b5b', false, NULL, '2026-11-10 10:57:20+00')
       ) AS v(team, card, day, from_stage, from_state, to_stage, to_state,
              participant, facilitator, request, is_manual, comment, at)
  LEFT JOIN demo_stage fs ON fs.code = v.from_stage
  JOIN demo_stage ts ON ts.code = v.to_stage
 ORDER BY v.at;

